ITEMS = [
 {"n": 1, "q": {"tr": "İlm-i bedî' nedir?", "en": "What is the science of badīʿ?"},
  "a": {"tr": "Mutâbakata riâyet ve delâletin vuzûhundan sonra, kelâmı güzelleştirme vecihlerinin kendisiyle bilindiği ilimdir; balâgatın üçüncü fennidir.", "en": "A science by which are known the ways of beautifying speech, after the words have been fitted to the situation and the sense made plain; the third art of balāgha."},
  "ar": ["عِلْمٌ يُعْرَفُ بِهِ وُجُوهُ تَحْسِينِ الْكَلَامِ بَعْدَ رِعَايَةِ الْمُطَابَقَةِ وَوُضُوحِ الدَّلَالَةِ"], "notes": ["ilm-al-badi"]},
 {"n": 2, "q": {"tr": "Kelâmı güzelleştiren vecihler kaç kısımdır?", "en": "How many kinds are the ways of beautifying speech?"},
  "a": {"tr": "İki: mânevî (muhassinât-ı mâneviyye) ve lafzî (muhassinât-ı lafziyye).", "en": "Two: of the meaning (the maʿnawī embellishments) and of the wording (the lafẓī)."},
  "ar": ["وَهِيَ ضَرْبَانِ مَعْنَوِيٌّ وَلَفْظِيٌّ"], "notes": ["ilm-al-badi"]},
 {"n": 3, "q": {"tr": "San'at-ı tıbâk nedir?", "en": "What is the figure of ṭibāq?"},
  "a": {"tr": "Mutâbaka: bir cümlede iki mütezâd, yani birbirine mukabil iki mânâyı cem etmektir; tıbâk ve tezâd da denir. İki isimle (أَيْقَاظًا – رُقُودٌ), iki fiille (يُحْيِي وَيُمِيتُ), iki harfle (لَهَا – عَلَيْهَا) veya iki nevi ile olur; tıbâk-ı îcâb ve tıbâk-ı selb olmak üzere iki kısımdır.", "en": "The muṭābaqa: gathering two contraries — two opposed meanings — in one sentence; also called ṭibāq and taḍādd. It comes with two nouns (أَيْقَاظًا – رُقُودٌ), two verbs (يُحْيِي وَيُمِيتُ), two particles (لَهَا – عَلَيْهَا) or two words of two kinds, and is of two sorts: of affirmation and of negation."},
  "ar": ["الْجَمْعُ بَيْنَ مُتَضَادَّيْنِ أَيْ مَعْنَيَيْنِ مُتَقَابِلَيْنِ فِي الْجُمْلَةِ", "يُحْيِي وَيُمِيتُ"], "notes": ["tibaq"]},
 {"n": 4, "q": {"tr": "Mukabele nedir?", "en": "What is the muqābala?"},
  "a": {"tr": "İki veya daha fazla uyumlu mânâ getirip sonra bunların mukabilini tertib üzere getirmektir: فَلْيَضْحَكُوا قَلِيلًا وَلْيَبْكُوا كَثِيرًا. Sekkâkî'ye göre burada bir şey şart kılınınca orada zıddı şart kılınır.", "en": "Bringing two agreeing meanings, or more, and then what counters them, in order: فَلْيَضْحَكُوا قَلِيلًا وَلْيَبْكُوا كَثِيرًا. Al-Sakkākī adds that when a thing is made a condition here, its contrary is the condition there."},
  "ar": ["أَنْ يُؤْتَى بِمَعْنَيَيْنِ مُتَوَافِقَيْنِ أَوْ أَكْثَرَ ثُمَّ بِمَا يُقَابِلُ ذَلِكَ عَلَى التَّرْتِيبِ", "فَلْيَضْحَكُوا قَلِيلًا وَلْيَبْكُوا كَثِيرًا"], "notes": ["muqabala"]},
 {"n": 5, "q": {"tr": "Mürâât-ı nazîr nedir?", "en": "What is murāʿāt al-naẓīr?"},
  "a": {"tr": "Bir şeyi ve ona münasip olanı, tezâd yoluyla olmaksızın cem etmektir; tenâsüb ve tevfîk de denir: الشَّمْسُ وَالْقَمَرُ بِحُسْبَانٍ.", "en": "Gathering a thing and what suits it — not by contrariety; also called the tanāsub and the tawfīq: الشَّمْسُ وَالْقَمَرُ بِحُسْبَانٍ."},
  "ar": ["جَمْعُ أَمْرٍ وَمَا يُنَاسِبُهُ لَا بِالتَّضَادِّ", "الشَّمْسُ وَالْقَمَرُ بِحُسْبَانٍ"], "notes": ["muraat-al-nazir"]},
 {"n": 6, "q": {"tr": "Teşâbühü'l-etrâf nedir?", "en": "What is tashābuh al-aṭrāf?"},
  "a": {"tr": "Kelâmı, mânâ bakımından başlangıcına münasip olanla bitirmektir: لَا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ. Bir şeyi, iki mânâsından murad olmayanıyla ona münasip olanla cem etmek olan îhâmü't-tenâsüb de buna mülhaktır.", "en": "Closing the speech with what suits its opening in meaning: لَا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ. Joined to it is īhām al-tanāsub — gathering a thing with what suits it in the sense that is not meant."},
  "ar": ["أَنْ يُخْتَمَ الْكَلَامُ بِمَا يُنَاسِبُ ابْتِدَاءَهُ فِي الْمَعْنَى"], "notes": ["tashabuh-al-atraf", "iham-al-tanasub"]},
 {"n": 7, "q": {"tr": "İrsâd nedir?", "en": "What is the irṣād?"},
  "a": {"tr": "Teshîm de denir: fıkranın veya beytin acüzünden önce, revî bilindiğinde ona delâlet edecek şeyi koymaktır: فَمَا كَانَ اللهُ لِيَظْلِمَهُمْ وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ.", "en": "Also called the tashīm: setting before the close of the prose clause or the verse what points to it once the rhyme-letter is known: فَمَا كَانَ اللهُ لِيَظْلِمَهُمْ وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ."},
  "ar": ["أَنْ يُجْعَلَ قَبْلَ الْعَجُزِ مِنَ الْفِقْرَةِ أَوِ الْبَيْتِ مَا يَدُلُّ عَلَيْهِ إِذَا عُرِفَ الرَّوِيُّ"], "notes": ["irsad"]},
 {"n": 8, "q": {"tr": "Müşâkele nedir?", "en": "What is the mushākala?"},
  "a": {"tr": "Bir şeyi, tahkîkan veya takdîren onun sohbetinde vâki olduğu için başkasının lafzıyla zikretmektir: قَالُوا اقْتَرِحْ شَيْئًا نُجِدْ لَكَ طَبْخَهُ قُلْتُ اطْبُخُوا لِي جُبَّةً وَقَمِيصًا; تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ; takdîren: صِبْغَةَ اللهِ.", "en": "Mentioning a thing by another's word because it falls in that other's company, in fact or in estimation: قَالُوا اقْتَرِحْ شَيْئًا نُجِدْ لَكَ طَبْخَهُ قُلْتُ اطْبُخُوا لِي جُبَّةً وَقَمِيصًا; تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ; by estimation: صِبْغَةَ اللهِ."},
  "ar": ["ذِكْرُ الشَّيْءِ بِلَفْظِ غَيْرِهِ لِوُقُوعِهِ فِي صُحْبَتِهِ تَحْقِيقًا أَوْ تَقْدِيرًا"], "notes": ["mushakala"]},
 {"n": 9, "q": {"tr": "Müzâvece nedir?", "en": "What is the muzāwaja?"},
  "a": {"tr": "Şart ve cezâda iki mânâ arasında, her birine bir mânâ terettüb ettirilerek çiftleştirmektir: إِذَا مَا نَهَى النَّاهِي فَلَجَّ بِيَ الْهَوَى • أَصَاخَتْ إِلَى الْوَاشِي فَلَجَّ بِهَا الْهَجْرُ.", "en": "Pairing two meanings in the condition and its answer so that one consequence follows each: إِذَا مَا نَهَى النَّاهِي فَلَجَّ بِيَ الْهَوَى • أَصَاخَتْ إِلَى الْوَاشِي فَلَجَّ بِهَا الْهَجْرُ."},
  "ar": ["أَنْ يُزَاوَجَ بَيْنَ مَعْنَيَيْنِ فِي الشَّرْطِ وَالْجَزَاءِ بِأَنْ يُرَتَّبَ عَلَى كُلٍّ مِنْهُمَا مَعْنًى وَاحِدٌ"], "notes": ["muzawaja"]},
 {"n": 10, "q": {"tr": "Aks nedir?", "en": "What is the ʿaks?"},
  "a": {"tr": "Kelâmda bir cüz'ü önce getirip sonra sona almaktır; birkaç vech üzere olur: bir cümlenin iki tarafından biri ile ona muzâf olan arasında (عَادَاتُ السَّادَاتِ سَادَاتُ الْعَادَاتِ); iki cümlede iki fiilin müteallakları arasında (يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ); iki cümlenin iki tarafındaki iki lafız arasında (لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ).", "en": "Putting a part of the speech first and then last; in several shapes: between one end of a sentence and what is annexed to it (عَادَاتُ السَّادَاتِ سَادَاتُ الْعَادَاتِ); between the dependents of two verbs in two sentences (يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ); between two words at the ends of two sentences (لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ)."},
  "ar": ["أَنْ يُقَدَّمَ فِي الْكَلَامِ جُزْءٌ ثُمَّ يُؤَخَّرَ", "عَادَاتُ السَّادَاتِ سَادَاتُ الْعَادَاتِ"], "notes": ["aks"]},
 {"n": 11, "q": {"tr": "Rücû' nedir?", "en": "What is the rujūʿ?"},
  "a": {"tr": "Bir nükte için önceki kelâma nakz ile dönmektir: قِفْ بِالدِّيَارِ الَّتِي لَمْ يَعْفُهَا الْقِدَمُ • بَلَى وَغَيَّرَهَا الْأَرْوَاحُ وَالدِّيَمُ.", "en": "Returning to the preceding speech by retracting it, for a point: قِفْ بِالدِّيَارِ الَّتِي لَمْ يَعْفُهَا الْقِدَمُ • بَلَى وَغَيَّرَهَا الْأَرْوَاحُ وَالدِّيَمُ."},
  "ar": ["الْعَوْدُ إِلَى الْكَلَامِ السَّابِقِ بِالنَّقْضِ لِنُكْتَةٍ"], "notes": ["ruju"]},
 {"n": 12, "q": {"tr": "Tevriye nedir?", "en": "What is the tawriya?"},
  "a": {"tr": "Îhâm da denir: biri yakın biri uzak iki mânâsı olan bir lafzı söyleyip uzak mânâyı murad etmektir. İki kısımdır: mücerrede — yakın mânâya münasip bir şeyle beraber olmayan (الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى); müreşşaha — yakın mânâya münasip bir şeyle beraber olan (وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ).", "en": "Also called the īhām: using a word with two senses, a near and a far, and meaning the far. Two kinds: the bare, joined with nothing that suits the near sense (الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى); the furnished, joined with something that suits it (وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ)."},
  "ar": ["أَنْ يُطْلَقَ لَفْظٌ لَهُ مَعْنَيَانِ قَرِيبٌ وَبَعِيدٌ وَيُرَادَ الْبَعِيدُ"], "notes": ["tawriya"]},
 {"n": 13, "q": {"tr": "İstihdâm nedir?", "en": "What is the istikhdām?"},
  "a": {"tr": "İki mânâsı olan bir lafızla birini, sonra zamiriyle diğerini murad etmek; veya iki zamirinden biriyle birini, diğeriyle diğerini murad etmektir. Birincisine: إِذَا نَزَلَ السَّمَاءُ بِأَرْضِ قَوْمٍ • رَعَيْنَاهُ وَإِنْ كَانُوا غِضَابًا (semâ ile yağmur, zamirle ot); ikincisine: فَسَقَى الْغَضَا وَالسَّاكِنِيهِ وَإِنْ هُمُ • شَبُّوهُ بَيْنَ جَوَانِحِي وَضُلُوعِي.", "en": "Meaning by a word with two senses one of them, then by its pronoun the other; or by one of its two pronouns one sense and by the other the other. The first: إِذَا نَزَلَ السَّمَاءُ بِأَرْضِ قَوْمٍ • رَعَيْنَاهُ وَإِنْ كَانُوا غِضَابًا (by «sky» the rain, by its pronoun the herbage); the second: فَسَقَى الْغَضَا وَالسَّاكِنِيهِ وَإِنْ هُمُ • شَبُّوهُ بَيْنَ جَوَانِحِي وَضُلُوعِي."},
  "ar": ["أَنْ يُرَادَ بِلَفْظٍ لَهُ مَعْنَيَانِ أَحَدُهُمَا ثُمَّ بِضَمِيرِهِ الْآخَرُ"], "notes": ["istikhdam"]},
 {"n": 14, "q": {"tr": "Leff ü neşr nedir?", "en": "What is the laff wa-nashr?"},
  "a": {"tr": "Birçok şeyi tafsîlen veya icmâlen zikredip sonra her birine ait olanı, dinleyenin ona döndüreceğine güvenerek tayinsiz zikretmektir. Tafsîlî, müretteb (جَعَلَ لَكُمُ اللَّيْلَ وَالنَّهَارَ لِتَسْكُنُوا فِيهِ وَلِتَبْتَغُوا مِنْ فَضْلِهِ) ve gayr-i müretteb (كَيْفَ أَسْلُو وَأَنْتِ حِقْفٌ وَغُصْنٌ • وَغَزَالٌ لَحْظًا وَقَدًّا وَرِدْفًا) olur; icmâlî: وَقَالُوا لَنْ يَدْخُلَ الْجَنَّةَ إِلَّا مَنْ كَانَ هُودًا أَوْ نَصَارَى.", "en": "Mentioning several things, in detail or in sum, then what belongs to each without specifying — trusting the hearer to return each to its own. The detailed is ordered (جَعَلَ لَكُمُ اللَّيْلَ وَالنَّهَارَ لِتَسْكُنُوا فِيهِ وَلِتَبْتَغُوا مِنْ فَضْلِهِ) or unordered (كَيْفَ أَسْلُو وَأَنْتِ حِقْفٌ وَغُصْنٌ • وَغَزَالٌ لَحْظًا وَقَدًّا وَرِدْفًا); the summed: وَقَالُوا لَنْ يَدْخُلَ الْجَنَّةَ إِلَّا مَنْ كَانَ هُودًا أَوْ نَصَارَى."},
  "ar": ["ذِكْرُ مُتَعَدِّدٍ عَلَى التَّفْصِيلِ أَوِ الْإِجْمَالِ ثُمَّ ذِكْرُ مَا لِكُلٍّ مِنْ غَيْرِ تَعْيِينٍ"], "notes": ["laff-wa-nashr"]},
 {"n": 15, "q": {"tr": "Cem' nedir?", "en": "What is the jamʿ?"},
  "a": {"tr": "Birçok şeyi bir hükümde cem etmektir: الْمَالُ وَالْبَنُونَ زِينَةُ الْحَيَاةِ الدُّنْيَا; إِنَّ الشَّبَابَ وَالْفَرَاغَ وَالْجِدَةَ • مَفْسَدَةٌ لِلْمَرْءِ أَيُّ مَفْسَدَةٍ.", "en": "Gathering many things under one ruling: الْمَالُ وَالْبَنُونَ زِينَةُ الْحَيَاةِ الدُّنْيَا; إِنَّ الشَّبَابَ وَالْفَرَاغَ وَالْجِدَةَ • مَفْسَدَةٌ لِلْمَرْءِ أَيُّ مَفْسَدَةٍ."},
  "ar": ["أَنْ يُجْمَعَ بَيْنَ مُتَعَدِّدٍ فِي حُكْمٍ", "الْمَالُ وَالْبَنُونَ زِينَةُ الْحَيَاةِ الدُّنْيَا"], "notes": ["jam"]},
 {"n": 16, "q": {"tr": "Tefrîk ve taksim nedir?", "en": "What are the tafrīq and the taqsīm?"},
  "a": {"tr": "Tefrîk: medihte veya başka bir şeyde, bir nevi'den iki şey arasına ayrılık koymaktır (مَا نَوَالُ الْغَمَامِ وَقْتَ رَبِيعٍ • كَنَوَالِ الْأَمِيرِ يَوْمَ سَخَاءِ). Taksim: birçok şeyi zikredip sonra her birine ait olanı tayin üzere ona izâfe etmektir (إِلَّا الْأَذَلَّانِ عَيْرُ الْحَيِّ وَالْوَتَدُ • هَذَا عَلَى الْخَسْفِ مَرْبُوطٌ بِرُمَّتِهِ • وَذَا يُشَجُّ فَلَا يَرْثِي لَهُ أَحَدُ).", "en": "The tafrīq: striking a difference between two things of one kind, in praise or otherwise (مَا نَوَالُ الْغَمَامِ وَقْتَ رَبِيعٍ • كَنَوَالِ الْأَمِيرِ يَوْمَ سَخَاءِ). The taqsīm: naming many things, then adding to each what belongs to it, one by one (إِلَّا الْأَذَلَّانِ عَيْرُ الْحَيِّ وَالْوَتَدُ • هَذَا عَلَى الْخَسْفِ مَرْبُوطٌ بِرُمَّتِهِ • وَذَا يُشَجُّ فَلَا يَرْثِي لَهُ أَحَدُ)."},
  "ar": ["إِيقَاعُ تَبَايُنٍ بَيْنَ أَمْرَيْنِ مِنْ نَوْعٍ وَاحِدٍ فِي الْمَدْحِ أَوْ غَيْرِهِ", "ذِكْرُ مُتَعَدِّدٍ ثُمَّ إِضَافَةُ مَا لِكُلٍّ إِلَيْهِ عَلَى التَّعْيِينِ"], "notes": ["tafriq", "taqsim"]},
 {"n": 17, "q": {"tr": "Cem' maa't-tefrîk nedir?", "en": "What is the jamʿ with tafrīq?"},
  "a": {"tr": "İki şeyi bir mânâya dâhil edip dâhil etmenin iki cihetini birbirinden ayırmaktır: فَوَجْهُكَ كَالنَّارِ فِي ضَوْئِهَا • وَقَلْبِي كَالنَّارِ فِي حَرِّهَا.", "en": "Bringing two things into one meaning and then setting apart the two sides of that entry: فَوَجْهُكَ كَالنَّارِ فِي ضَوْئِهَا • وَقَلْبِي كَالنَّارِ فِي حَرِّهَا."},
  "ar": ["أَنْ يُدْخَلَ شَيْئَانِ فِي مَعْنًى وَيُفَرَّقَ بَيْنَ جِهَتَيِ الْإِدْخَالِ"], "notes": ["jam-maa-tafriq-taqsim"]},
 {"n": 18, "q": {"tr": "Cem' maa't-taksim nedir?", "en": "What is the jamʿ with taqsīm?"},
  "a": {"tr": "Birçok şeyi bir hüküm altında cem edip sonra taksim etmek, veya taksim edip sonra cem etmektir. Birincisi Mütenebbî'nin حَتَّى أَقَامَ عَلَى أَرْبَاضِ خَرْشَنَةٍ • تَشْقَى بِهِ الرُّومُ وَالصُّلْبَانُ وَالْبِيَعُ • لِلسَّبْيِ مَا نَكَحُوا وَالْقَتْلِ مَا وَلَدُوا … beyitleri; ikincisi Hassân'ın قَوْمٌ إِذَا حَارَبُوا ضَرُّوا عَدُوَّهُمْ … سَجِيَّةٌ تِلْكَ مِنْهُمْ غَيْرُ مُحْدَثَةٍ beyitleri. Cem' maa't-tefrîk ve't-taksim de vardır: يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِ فَمِنْهُمْ شَقِيٌّ وَسَعِيدٌ.", "en": "Gathering many things under one ruling and then dividing them, or dividing first and then gathering. The first: al-Mutanabbī's حَتَّى أَقَامَ عَلَى أَرْبَاضِ خَرْشَنَةٍ • تَشْقَى بِهِ الرُّومُ وَالصُّلْبَانُ وَالْبِيَعُ • لِلسَّبْيِ مَا نَكَحُوا وَالْقَتْلِ مَا وَلَدُوا …; the second: Ḥassān's قَوْمٌ إِذَا حَارَبُوا ضَرُّوا عَدُوَّهُمْ … سَجِيَّةٌ تِلْكَ مِنْهُمْ غَيْرُ مُحْدَثَةٍ. There is also the jamʿ with tafrīq and taqsīm together: يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِ فَمِنْهُمْ شَقِيٌّ وَسَعِيدٌ."},
  "ar": ["جَمْعُ مُتَعَدِّدٍ تَحْتَ حُكْمٍ ثُمَّ تَقْسِيمُهُ أَوْ تَقْسِيمُهُ ثُمَّ جَمْعُهُ"], "notes": ["jam-maa-tafriq-taqsim", "taqsim-al-ahwal-wal-istifa"]},
 {"n": 19, "q": {"tr": "Tecrîd nedir?", "en": "What is the tajrīd?"},
  "a": {"tr": "Bir vasfı olan şeyden, o vasıfta onun gibi başka bir şeyi, vasfın onda kemâli sebebiyle mübalağa için çekip çıkarmaktır. Kısımları: مِنْ ile (لِي مِنْ فُلَانٍ صَدِيقٌ حَمِيمٌ), bâ ile (لَئِنْ سَأَلْتَ فُلَانًا لَتَسْأَلَنَّ بِهِ الْبَحْرَ), bâ-i maiyye ile, فِي ile (لَهُمْ فِيهَا دَارُ الْخُلْدِ), harfsiz, kinâye yoluyla ve insanın kendine hitabıyla (لَا خَيْلَ عِنْدَكَ تُهْدِيهَا وَلَا مَالُ • فَلْيُسْعِدِ النُّطْقُ إِنْ لَمْ تُسْعِدِ الْحَالُ).", "en": "Drawing out of a thing that has a quality another thing like it in that quality, for hyperbole, because the quality is complete in it. Its kinds: by مِنْ (لِي مِنْ فُلَانٍ صَدِيقٌ حَمِيمٌ), by the bāʾ (لَئِنْ سَأَلْتَ فُلَانًا لَتَسْأَلَنَّ بِهِ الْبَحْرَ), by the bāʾ of accompaniment, by فِي (لَهُمْ فِيهَا دَارُ الْخُلْدِ), without a letter, by way of kināya, and by a man addressing himself (لَا خَيْلَ عِنْدَكَ تُهْدِيهَا وَلَا مَالُ • فَلْيُسْعِدِ النُّطْقُ إِنْ لَمْ تُسْعِدِ الْحَالُ)."},
  "ar": ["أَنْ يُنْتَزَعَ مِنْ أَمْرٍ ذِي صِفَةٍ أَمْرٌ آخَرُ مِثْلُهُ فِيهَا مُبَالَغَةً لِكَمَالِهَا فِيهِ"], "notes": ["tajrid"]},
 {"n": 20, "q": {"tr": "Mübalağa nedir?", "en": "What is the mubālagha?"},
  "a": {"tr": "Mübalağa-i makbûle: bir vasıf için şiddette veya zaafta müstahîl veya müsteb'ad bir hadde ulaştığını iddia etmektir. Üç kısımdır: teblîğ (aklen ve âdeten mümkün), iğrâk (aklen mümkün, âdeten değil), gulüv (ne aklen ne âdeten mümkün); ilk ikisi makbuldür. Gulüvden de, sıhhate yaklaştıran bir şey giren (يَكَادُ زَيْتُهَا يُضِيءُ), güzel bir tahyîl taşıyan ve hezl yoluyla söylenen makbuldür.", "en": "The accepted mubālagha: claiming for a quality that it reaches, in strength or weakness, a degree impossible or far-fetched. Three kinds: tablīgh (possible in reason and custom), ighrāq (possible in reason, not in custom), ghuluww (possible in neither); the first two are accepted. Of ghuluww, what a nearing word enters (يَكَادُ زَيْتُهَا يُضِيءُ), what carries a fine fancy, and what comes out in jest is accepted."},
  "ar": ["أَنْ يُدَّعَى لِوَصْفٍ بُلُوغُهُ فِي الشِّدَّةِ أَوِ الضَّعْفِ حَدًّا مُسْتَحِيلًا أَوْ مُسْتَبْعَدًا"], "notes": ["mubalagha-maqbula"]},
 {"n": 21, "q": {"tr": "Mezheb-i kelâmî nedir?", "en": "What is the madhhab kalāmī?"},
  "a": {"tr": "Matlûb için ehl-i kelâmın yolu üzere hüccet getirmektir: لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللهُ لَفَسَدَتَا; Nâbiga'nın حَلَفْتُ فَلَمْ أَتْرُكْ لِنَفْسِكَ رِيبَةً beyitleri.", "en": "Bringing a proof for the claim in the manner of the people of kalām: لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللهُ لَفَسَدَتَا; al-Nābigha's حَلَفْتُ فَلَمْ أَتْرُكْ لِنَفْسِكَ رِيبَةً."},
  "ar": ["إِيرَادُ حُجَّةٍ لِلْمَطْلُوبِ عَلَى طَرِيقَةِ أَهْلِ الْكَلَامِ", "لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللهُ لَفَسَدَتَا"], "notes": ["madhhab-kalami"]},
 {"n": 22, "q": {"tr": "Hüsn-i ta'lîl nedir?", "en": "What is ḥusn al-taʿlīl?"},
  "a": {"tr": "Bir vasıf için, hakikî olmayan latîf bir itibarla ona münasip bir illet iddia etmektir. Dört kısımdır: vasıf sâbit olup âdette illeti görünmez (لَمْ يَحْكِ نَائِلَكَ السَّحَابُ وَإِنَّمَا • حُمَّتْ بِهِ فَصَبِيبُهَا الرُّحَضَاءُ) veya zikredilenden başka bir illeti görünür; vasıf sâbit olmayıp isbatı kastedilir — mümkün veya gayr-i mümkün. Şek üzerine binâ edilen de buna mülhaktır (كَأَنَّ السَّحَابَ الْغُرَّ غَيَّبْنَ تَحْتَهَا • حَبِيبًا).", "en": "Claiming for a quality a cause that suits it by a fine, unreal consideration. Four kinds: the quality is fixed and no cause for it appears in custom (لَمْ يَحْكِ نَائِلَكَ السَّحَابُ وَإِنَّمَا • حُمَّتْ بِهِ فَصَبِيبُهَا الرُّحَضَاءُ), or a cause other than the one named appears; or the quality is not fixed and its proving is intended — possible or not. What is built on doubt is joined to it (كَأَنَّ السَّحَابَ الْغُرَّ غَيَّبْنَ تَحْتَهَا • حَبِيبًا)."},
  "ar": ["أَنْ يُدَّعَى لِوَصْفٍ عِلَّةٌ مُنَاسِبَةٌ لَهُ بِاعْتِبَارٍ لَطِيفٍ غَيْرِ حَقِيقِيٍّ"], "notes": ["husn-al-talil"]},
]
